  height: 12px !important;                /* 【调节】小加号圆圈高度 */
  border-radius: 50% !important;
  background: #080830 !important;
  color: #FFFFFF !important;
  border: 1.2px solid #FFFFFF !important;
  font-size: 9px !important;
  font-weight: 900 !important;
  line-height: 9.5px !important;
  text-align: center !important;
  pointer-events: none !important;
}

/* 12.4 中间打字框容器 (.input-action-bar-custom)：内部全透明 + 方圆角 7px */
.chat-detail-screen .input-action-bar-custom {
  flex: 1 1 auto !important;
  min-width: 0 !important;
  display: flex !important;
  align-items: center !important;
  background: transparent !important;
  background-color: transparent !important;
  border: 1.2px solid #080830 !important;
  border-radius: 7px !important;          /* 【调节】打字框圆角：7px 为方圆角（5px 更方，999px 为椭圆胶囊） */
  box-shadow: none !important;
  padding: 0 10px 0 12px !important;      /* 【调节】打字框内部左右内边距：右10px、左12px */
  height: 36px !important;                /* 【调节】打字框整体高度 */
  box-sizing: border-box !important;
  position: relative !important;
  overflow: visible !important;
  margin-right: 78px !important;          /* 【调节】打字框右侧预留给「麦克风+AI按钮」的宽度（改大打字框变短，改小打字框变长） */
}

/* 12.5 输入框文字本体 (.input-box-custom) */
.chat-detail-screen .input-box-custom {
