  line-height: 36px !important;
  font-size: 13.5px !important;           /* 【调节】占位文字字号大小 */
  color: #405880 !important;
  font-weight: 500 !important;
  pointer-events: none !important;
  white-space: nowrap !important;
  z-index: 1 !important;
}

.chat-detail-screen .input-action-bar-custom:focus-within::before,
.chat-detail-screen .input-action-bar-custom:has(textarea:not(:placeholder-shown))::before {
  display: none !important;
}

/* 12.7 右侧第 1 个大图标：表情贴纸按钮（.input-btn-sticker，#EBF1F8 冰白内胆 + #080830 线条） */
.chat-detail-screen .input-btn-sticker {
  position: relative !important;
  flex-shrink: 0 !important;
  width: 28px !important;                 /* 【调节】贴纸按钮点击区宽度 */
