    border-right: 1.5px solid #70A0D0 !important;
  }

  /* --------------------------------------------------------------------------
     6. 文字翻译条（夜间大背景是深黑蓝，左右两边统一为 #E8EFF7 冰白底 + #080830 深海蓝字 + 无描边！）
     -------------------------------------------------------------------------- */
  .chat-detail-screen .msg-translation-detached-content,
  .chat-detail-screen .msg-them .msg-translation-detached-content,
  .chat-detail-screen .msg-me .msg-translation-detached-content {
